import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../widgets/sydex_ui.dart';
import '../../theme/sydex_theme.dart';

/// Owner-only chat assistant for questions about business figures.
/// Answers are generated by the owner-ai-assistant Supabase Edge Function.
class OwnerAIAssistantScreen extends StatefulWidget {
  const OwnerAIAssistantScreen({super.key});

  @override
  State<OwnerAIAssistantScreen> createState() => _OwnerAIAssistantScreenState();
}

class _OwnerAIAssistantScreenState extends State<OwnerAIAssistantScreen> {
  final SupabaseClient _supabase = Supabase.instance.client;
  final TextEditingController _questionController = TextEditingController();
  final ScrollController _scrollController = ScrollController();

  final List<_AssistantMessage> _messages = [
    _AssistantMessage(
      text:
          "Hi! I'm Sydie 😊 I’m here to help you use Sydex. Ask me anything about the app, your collections, sales, routes, payments, or customers.",
      isUser: false,
    ),
  ];

  bool _sending = false;

  static const List<String> _suggestions = [
    "How much is today's collection?",
    "What is the total outstanding?",
  ];

  @override
  void dispose() {
    _questionController.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  Future<void> _sendQuestion([String? suggested]) async {
    if (_sending) return;
    final question = (suggested ?? _questionController.text).trim();
    if (question.isEmpty) return;

    setState(() {
      _messages.add(_AssistantMessage(text: question, isUser: true));
      _questionController.clear();
      _sending = true;
    });
    _scrollToBottom();

    try {
      final localAnswer = _appHelpAnswer(question);
      if (localAnswer != null) {
        if (mounted) {
          setState(() {
            _messages.add(_AssistantMessage(text: localAnswer, isUser: false));
          });
        }
        return;
      }
      final response = await _supabase.functions.invoke(
        'owner-ai-assistant',
        body: <String, dynamic>{
          'question': question,
          'app_context': '''
You are Sydie, the friendly Sydex in-app helper. Be warm, patient, encouraging,
and conversational. Understand natural, informal questions and answer without
making the user feel technical or judged. Use short, clear step-by-step
instructions when navigation is needed. Sydex includes
Owner and Salesman dashboards, customers and ledgers, sales, payments, cheque
bounce handling, routes, salesman assignments, reports, receipts, settings,
dark/light mode, subscription billing, and hiding payments from the owner
ledger. Explain where to tap and what each action does. Never invent data or
claim a payment was changed; for business figures use only verified data
available to the function.
''',
        },
      );

      final data = response.data;
      if (response.status < 200 || response.status >= 300) {
        final message = data is Map
            ? (data['error'] ?? 'The assistant request failed.').toString()
            : 'The assistant request failed (HTTP ${response.status}).';
        throw Exception(message);
      }
      if (data is! Map || data['answer'] == null) {
        throw const FormatException(
          'The assistant returned an unexpected response.',
        );
      }

      final answer = data['answer'].toString();
      if (mounted) {
        setState(() {
          _messages.add(_AssistantMessage(text: answer, isUser: false));
        });
      }
    } catch (error) {
      if (mounted) {
        setState(() {
          _messages.add(
            _AssistantMessage(
              text: _friendlyError(error),
              isUser: false,
              isError: true,
            ),
          );
        });
      }
    } finally {
      if (mounted) setState(() => _sending = false);
      _scrollToBottom();
    }
  }

  String? _appHelpAnswer(String question) {
    final text = question.toLowerCase();
    if (RegExp(r'^(hi|hello|hey| hai|good morning|good afternoon|good evening)\b')
        .hasMatch(text)) {
      return 'Hi there 😊 I’m Sydie. What would you like help with in Sydex today?';
    }
    if (text.contains('how are you') || text.contains('how do you feel')) {
      return 'I’m doing great and ready to help 😊 What are you working on in Sydex?';
    }
    if (text.contains('thank') || text.contains('thanks')) {
      return 'You’re very welcome 😊 I’m always happy to help.';
    }
    if (text.contains('who are you') || text.contains('your name')) {
      return 'I’m Sydie, your friendly Sydex helper. I can explain the app and help you find features.';
    }
    if ((text.contains('hide') || text.contains('remove') || text.contains('not show')) &&
        (text.contains('payment') || text.contains('ledger') || text.contains('entry'))) {
      return 'To hide a transaction: open the customer history and press that transaction for a moment. Sydie will show Hide from ledger. Tap it to remove the entry from the ledger view without deleting the payment record. You can still find it in the customer history.';
    }
    if ((text.contains('assign') || text.contains('give') || text.contains('add')) &&
        (text.contains('salesman') || text.contains('route') || text.contains('executive'))) {
      return 'To assign customers: open Owner → Routes & Areas, create or select a route, choose customers, save the selection, then open Assign route to salesmen and select the salesman. The salesman will see only those assigned customers.';
    }
    if (text.contains('new sale') || text.contains('new purchase') ||
        text.contains('record sale') || text.contains('make a sale')) {
      return 'To create a sale: open Owner → Sales, choose the customer, enter the sale amount and items, then save. You can also use the Add Sale button on the dashboard.';
    }
    if (text.contains('settings') || text.contains('theme') || text.contains('dark mode')) {
      return 'Open Owner → Settings to change appearance, business settings, notifications, and subscription options.';
    }
    if (text.contains('route') && (text.contains('finish') || text.contains('complete'))) {
      return 'Salesmen finish a route from their route dashboard using Finish route. After finishing, the route payment history is no longer shown in Payment History, while customer-specific history remains available.';
    }
    if (text.contains('where') || text.contains('how') || text.contains('app')) {
      return 'I can guide you around Sydex. Ask about customers, sales, payments, routes, salesman assignments, reports, settings, hiding ledger payments, or subscription billing.';
    }
    return null;
  }

  String _friendlyError(Object error) {
    var message = error.toString().replaceFirst('Exception: ', '');
    message = message.replaceFirst('FormatException: ', '');
    if (message.contains('GEMINI_API_KEY') ||
        message.contains('AI is not configured')) {
      return 'AI is not configured yet. Check the GEMINI_API_KEY secret in your Supabase Edge Function settings.';
    }
    if (message.contains('Failed to fetch') ||
        message.contains('SocketException')) {
      return 'I could not connect. Check your internet connection and try again.';
    }
    return message;
  }

  void _scrollToBottom() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_scrollController.hasClients) return;
      _scrollController.animateTo(
        _scrollController.position.maxScrollExtent,
        duration: const Duration(milliseconds: 250),
        curve: Curves.easeOut,
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Scaffold(
      appBar: AppBar(
        titleSpacing: 4,
        title: Row(
          children: [
            Container(
              width: 34,
              height: 34,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: SydexColors.hero(context),
                borderRadius: BorderRadius.circular(10),
              ),
              child: const Icon(
                Icons.auto_awesome_rounded,
                size: 17,
                color: Colors.white,
              ),
            ),
            const SizedBox(width: 10),
            Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Sydie',
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.w600),
                ),
                Text(
                  'Answers from your live business figures',
                  style: TextStyle(
                    fontSize: 11.5,
                    color: theme.colorScheme.onSurfaceVariant,
                  ),
                ),
              ],
            ),
          ],
        ),
        actions: [
          IconButton(
            tooltip: 'Clear conversation',
            onPressed: _sending
                ? null
                : () => setState(() {
                    _messages
                      ..clear()
                      ..add(
                        _AssistantMessage(
                          text:
                              "Conversation cleared. What would you like to know about your business?",
                          isUser: false,
                        ),
                      );
                  }),
            icon: const Icon(Icons.refresh),
          ),
        ],
      ),
      body: SafeArea(
        child: Column(
          children: [
            Expanded(
              child: ListView(
                controller: _scrollController,
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
                children: [
                  if (_messages.length == 1) ...[
                    const SydexEyebrow('Ask in your own words'),
                    const SizedBox(height: 10),
                    Wrap(
                      spacing: 8,
                      runSpacing: 8,
                      children: _suggestions
                          .map(
                            (question) => ActionChip(
                              label: Text(question),
                              onPressed: _sending
                                  ? null
                                  : () => _sendQuestion(question),
                            ),
                          )
                          .toList(),
                    ),
                    const SizedBox(height: 18),
                  ],
                  ..._messages.map((message) => _buildMessage(message, theme)),
                  if (_sending)
                    const Padding(
                      padding: EdgeInsets.only(top: 8, bottom: 16),
                      child: Align(
                        alignment: Alignment.centerLeft,
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            SizedBox(
                              width: 16,
                              height: 16,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            ),
                            SizedBox(width: 10),
                            Text('Checking your business figures…'),
                          ],
                        ),
                      ),
                    ),
                ],
              ),
            ),
            Container(
              decoration: BoxDecoration(
                color: theme.colorScheme.surfaceContainerLowest,
                border: Border(
                  top: BorderSide(color: theme.colorScheme.outlineVariant),
                ),
              ),
              padding: const EdgeInsets.fromLTRB(16, 10, 16, 12),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Expanded(
                    child: TextField(
                      controller: _questionController,
                      minLines: 1,
                      maxLines: 5,
                      textInputAction: TextInputAction.send,
                      onSubmitted: (_) => _sendQuestion(),
                      enabled: !_sending,
                      decoration: const InputDecoration(
                        hintText: 'Ask about today’s collection…',
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  SydexIconButton(
                    icon: Icons.arrow_upward_rounded,
                    tooltip: 'Send question',
                    onPressed: _sending ? null : () => _sendQuestion(),
                    filled: true,
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildMessage(_AssistantMessage message, ThemeData theme) {
    final alignment = message.isUser
        ? Alignment.centerRight
        : Alignment.centerLeft;
    final color = message.isUser
        ? SydexColors.hero(context)
        : message.isError
        ? theme.colorScheme.errorContainer
        : theme.colorScheme.surface;
    final textColor = message.isUser
        ? Colors.white
        : message.isError
        ? theme.colorScheme.onErrorContainer
        : theme.colorScheme.onSurface;
    return Align(
      alignment: alignment,
      child: SydexReveal(
        child: Container(
          constraints: const BoxConstraints(maxWidth: 560),
          margin: const EdgeInsets.only(bottom: 10),
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
          decoration: BoxDecoration(
            color: color,
            border: message.isUser || message.isError
                ? null
                : Border.all(color: theme.colorScheme.outlineVariant),
            borderRadius: BorderRadius.only(
              topLeft: const Radius.circular(16),
              topRight: const Radius.circular(16),
              bottomLeft: Radius.circular(message.isUser ? 16 : 4),
              bottomRight: Radius.circular(message.isUser ? 4 : 16),
            ),
          ),
          child: SelectableText(
            message.text,
            style: theme.textTheme.bodyMedium?.copyWith(
              color: textColor,
              height: 1.45,
            ),
          ),
        ),
      ),
    );
  }
}

class _AssistantMessage {
  const _AssistantMessage({
    required this.text,
    required this.isUser,
    this.isError = false,
  });

  final String text;
  final bool isUser;
  final bool isError;
}
